import React, { useState, useEffect } from 'react';
import { ArrowUp, ArrowDown, Users, DollarSign, ShoppingCart, TrendingUp } from 'lucide-react';
import { fetchDashboardStats } from '../api/dashboard';
import type { StatsData } from '../types/dashboard';

interface StatsCardsProps {
  organizationId: string;
}

interface StatCardProps {
  title: string;
  value: string;
  change: number;
  icon: React.ReactNode;
  loading: boolean;
}

function StatCard({ title, value, change, icon, loading }: StatCardProps) {
  if (loading) {
    return (
      <div className="bg-white rounded-lg shadow p-6 animate-pulse">
        <div className="h-4 bg-gray-200 rounded w-1/2 mb-2" />
        <div className="h-8 bg-gray-200 rounded w-3/4" />
      </div>
    );
  }

  return (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-center justify-between">
        <div>
          <p className="text-sm font-medium text-gray-600">{title}</p>
          <p className="text-2xl font-bold text-gray-900 mt-1">{value}</p>
        </div>
        <div className="p-3 bg-blue-50 rounded-full">{icon}</div>
      </div>
      <div className="mt-4 flex items-center">
        {change >= 0 ? (
          <ArrowUp className="h-4 w-4 text-green-500" />
        ) : (
          <ArrowDown className="h-4 w-4 text-red-500" />
        )}
        <span
          className={`text-sm font-medium ml-1 ${
            change >= 0 ? 'text-green-600' : 'text-red-600'
          }`}
        >
          {Math.abs(change)}%
        </span>
        <span className="text-sm text-gray-500 ml-2">vs last period</span>
      </div>
    </div>
  );
}

export function StatsCards({ organizationId }: StatsCardsProps) {
  const [stats, setStats] = useState<StatsData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadStats() {
      setLoading(true);
      try {
        const data = await fetchDashboardStats(organizationId);
        setStats(data);
      } catch (err) {
        console.error('Failed to load stats:', err);
      } finally {
        setLoading(false);
      }
    }
    loadStats();
  }, [organizationId]);

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
      <StatCard
        title="Revenue"
        value={stats ? `$${stats.revenue.toLocaleString()}` : '--'}
        change={stats?.revenueChange ?? 0}
        icon={<DollarSign className="h-6 w-6 text-blue-600" />}
        loading={loading}
      />
      <StatCard
        title="Active Users"
        value={stats ? stats.activeUsers.toLocaleString() : '--'}
        change={stats?.usersChange ?? 0}
        icon={<Users className="h-6 w-6 text-blue-600" />}
        loading={loading}
      />
      <StatCard
        title="Orders"
        value={stats ? stats.orders.toLocaleString() : '--'}
        change={stats?.ordersChange ?? 0}
        icon={<ShoppingCart className="h-6 w-6 text-blue-600" />}
        loading={loading}
      />
      <StatCard
        title="Conversion Rate"
        value={stats ? `${stats.conversionRate}%` : '--'}
        change={stats?.conversionChange ?? 0}
        icon={<TrendingUp className="h-6 w-6 text-blue-600" />}
        loading={loading}
      />
    </div>
  );
}

