import React, { useState, useEffect } from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { fetchChartData } from '../api/dashboard';
import type { ChartPoint, DateRange } from '../types/dashboard';

interface ChartPanelProps {
  organizationId: string;
}

const DATE_RANGES: { label: string; value: DateRange }[] = [
  { label: '7 Days', value: '7d' },
  { label: '30 Days', value: '30d' },
  { label: '90 Days', value: '90d' },
  { label: '1 Year', value: '1y' },
];

export function ChartPanel({ organizationId }: ChartPanelProps) {
  const [chartData, setChartData] = useState<ChartPoint[]>([]);
  const [dateRange, setDateRange] = useState<DateRange>('7d');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadChartData() {
      setLoading(true);
      try {
        const data = await fetchChartData(organizationId, dateRange);
        setChartData(data);
      } catch (err) {
        console.error('Failed to load chart data:', err);
      } finally {
        setLoading(false);
      }
    }
    loadChartData();
  }, [organizationId, dateRange]);

  return (
    <div className="bg-white rounded-lg shadow p-6">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-lg font-semibold text-gray-900">Revenue Over Time</h2>
        <div className="flex space-x-2">
          {DATE_RANGES.map(({ label, value }) => (
            <button
              key={value}
              onClick={() => setDateRange(value)}
              className={`px-3 py-1 text-sm rounded-md transition-colors ${
                dateRange === value
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      {loading ? (
        <div className="h-64 flex items-center justify-center">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600" />
        </div>
      ) : (
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={chartData}>
            <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
            <XAxis
              dataKey="date"
              tick={{ fontSize: 12 }}
              tickFormatter={(val: string) =>
                new Date(val).toLocaleDateString('en-US', {
                  month: 'short',
                  day: 'numeric',
                })
              }
            />
            <YAxis
              tick={{ fontSize: 12 }}
              tickFormatter={(val: number) => `$${val.toLocaleString()}`}
            />
            <Tooltip
              formatter={(val: number) => [`$${val.toLocaleString()}`, 'Revenue']}
              labelFormatter={(label: string) =>
                new Date(label).toLocaleDateString('en-US', {
                  weekday: 'long',
                  month: 'long',
                  day: 'numeric',
                })
              }
            />
            <Line
              type="monotone"
              dataKey="revenue"
              stroke="#2563eb"
              strokeWidth={2}
              dot={false}
              activeDot={{ r: 6 }}
            />
          </LineChart>
        </ResponsiveContainer>
      )}
    </div>
  );
}

